1498	                // can be expensive) and also makes it so we don't need another
1499	                // cross-thread mailbox message within the IO path.
1500	                const scrollbar = state.terminal.screens.active.pages.scrollbar();
1501	
1502	                // Get our preedit state
1503	                const preedit: ?renderer.State.Preedit = preedit: {
1504	                    const p = state.preedit orelse break :preedit null;
1505	                    break :preedit try p.clone(arena_alloc);
1506	                };
1507	
1508	                // Rebuild our Kitty image placements when the placements
1509	                // or the images changed. The render state update above
1510	                // has already positioned every placement, so this is
1511	                // cheap. Most frames that only change text skip it.
1512	                if (self.images.kittyRequiresUpdate(
1513	                    state.terminal,
1514	                    &self.terminal_state,
1515	                )) {
1516	                    // We need to grab the draw mutex since this updates
1517	                    // our image state that drawFrame uses.
1518	                    self.draw_mutex.lockUncancelable(global.io());
1519	                    defer self.draw_mutex.unlock(global.io());
1520	                    self.images.kittyUpdate(
1521	                        self.alloc,
1522	                        state.terminal,
1523	                        &self.terminal_state,
1524	                    );
1525	                    self.images_rebuilt = true;
1526	                }
1527	
1528	                // Get our OSC8 links we're hovering if we have a mouse.
1529	                // This requires terminal state because of URLs.
1530	                const links: terminal.RenderState.CellSet = osc8: {
1531	                    // If our mouse isn't hovering, we have no links.
1532	                    const vp = state.mouse.point orelse break :osc8 .empty;
1533	
1534	                    // If the right mods aren't pressed, then we can't match.
1535	                    if (!state.mouse.mods.equal(inputpkg.ctrlOrSuper(.{})))
1536	                        break :osc8 .empty;
1537	
1538	                    break :osc8 self.terminal_state.linkCells(
1539	                        arena_alloc,
1540	                        vp,
1541	                    ) catch |err| {
1542	                        log.warn("error searching for OSC8 links err={}", .{err});
1543	                        break :osc8 .empty;
1544	                    };
1545	                };
1546	
1547	                const overlay_features: []const Overlay.Feature = overlay: {
1548	                    const insp = state.inspector orelse break :overlay &.{};
1549	                    const renderer_info = insp.rendererInfo();
1550	                    break :overlay renderer_info.overlayFeatures(
1551	                        arena_alloc,
1552	                    ) catch &.{};
1553	                };
1554	
1555	                break :critical .{
1556	                    .links = links,
1557	                    .mouse = state.mouse,
1558	                    .preedit = preedit,
1559	                    .scrollbar = scrollbar,
1560	                    .overlay_features = overlay_features,
1561	                };
1562	            };
1563	
1564	            // Outside the critical area, complete the update we began
1565	            // within it. This must be done before anything reads the
1566	            // render state (e.g. rebuildCells).
1567	            self.terminal_state.endUpdate();
1568	
1569	            // Outside the critical area we can update our links to contain
1570	            // our regex results.
1571	            self.config.links.renderCellMap(
1572	                arena_alloc,
1573	                &critical.links,
1574	                &self.terminal_state,
1575	                state.mouse.point,
1576	                state.mouse.mods,
1577	            ) catch |err| {
1578	                log.warn("error searching for regex links err={}", .{err});
1579	            };
1580	
1581	            // Clear our highlight state and update.
1582	            if (self.search_matches_dirty or self.terminal_state.dirty != .false) {
1583	                self.search_matches_dirty = false;
1584	
1585	                // Clear the prior highlights
1586	                const row_data = self.terminal_state.row_data.slice();
1587	                var any_dirty: bool = false;
1588	                for (
1589	                    row_data.items(.highlights),
1590	                    row_data.items(.dirty),
1591	                ) |*highlights, *dirty| {
1592	                    if (highlights.items.len > 0) {
1593	                        highlights.clearRetainingCapacity();
1594	                        dirty.* = true;
1595	                        any_dirty = true;
1596	                    }
1597	                }
1598	                if (any_dirty and self.terminal_state.dirty == .false) {
1599	                    self.terminal_state.dirty = .partial;
1600	                }
1601	
1602	                // NOTE: The order below matters. Highlights added earlier
1603	                // will take priority.
1604	
1605	                if (self.search_selected_match) |m| {
1606	                    self.terminal_state.updateHighlightsFlattened(
1607	                        self.alloc,
1608	                        @backingInt(HighlightTag.search_match_selected),
1609	                        &.{m.match},
1610	                    ) catch |err| {
1611	                        // Not a critical error, we just won't show highlights.
1612	                        log.warn("error updating search selected highlight err={}", .{err});
1613	                    };
1614	                }
1615	
1616	                if (self.search_matches) |m| {
1617	                    self.terminal_state.updateHighlightsFlattened(
1618	                        self.alloc,
1619	                        @backingInt(HighlightTag.search_match),
1620	                        m.matches,
1621	                    ) catch |err| {
1622	                        // Not a critical error, we just won't show highlights.
1623	                        log.warn("error updating search highlights err={}", .{err});
1624	                    };
1625	                }
1626	            }
1627	
1628	            // From this point forward no more errors.
1629	            errdefer comptime unreachable;
1630	
1631	            // Reset our dirty state after updating.
1632	            defer self.terminal_state.dirty = .false;
1633	
1634	            // Rebuild the overlay image if we have one. We can do this
1635	            // outside of any critical areas.
1636	            self.rebuildOverlay(
1637	                critical.overlay_features,
1638	            ) catch |err| {
1639	                log.warn(
1640	                    "error rebuilding overlay surface err={}",
1641	                    .{err},
1642	                );
1643	            };
1644	
1645	            // Acquire the draw mutex for all remaining state updates.
1646	            {
1647	                self.draw_mutex.lockUncancelable(global.io());
1648	                defer self.draw_mutex.unlock(global.io());
1649	
1650	                // Build our GPU cells
1651	                self.rebuildCells(
1652	                    critical.preedit,
1653	                    renderer.cursorStyle(&self.terminal_state, .{
1654	                        .preedit = critical.preedit != null,
1655	                        .focused = self.focused,
1656	                        .blink_visible = cursor_blink_visible,
1657	                    }),
1658	                    &critical.links,
1659	                ) catch |err| {
1660	                    // This means we weren't able to allocate our buffer
1661	                    // to update the cells. In this case, we continue with
1662	                    // our old buffer (frozen contents) and log it.
1663	                    comptime assert(@TypeOf(err) == error{OutOfMemory});
1664	                    log.warn("error rebuilding GPU cells err={}", .{err});
1665	                };
1666	
1667	                // The scrollbar is only emitted during draws so we also
1668	                // check the scrollbar cache here and update if needed.
1669	                // This is pretty fast.
1670	                if (!self.scrollbar.eql(critical.scrollbar)) {
1671	                    self.scrollbar = critical.scrollbar;
1672	                    self.scrollbar_dirty = true;
1673	                }
1674	
1675	                // Update our background color
1676	                self.uniforms.bg_color = .{
1677	                    self.terminal_state.colors.background.r,
1678	                    self.terminal_state.colors.background.g,
1679	                    self.terminal_state.colors.background.b,
1680	                    @intFromFloat(@round(self.config.background_opacity * 255.0)),
1681	                };
1682	
1683	                // If we're on macOS and have glass styles, we remove
1684	                // the background opacity because the glass effect handles
1685	                // it.
1686	                if (comptime builtin.target.os.tag == .macos) switch (self.config.background_blur) {
1687	                    .@"macos-glass-regular",
1688	                    .@"macos-glass-clear",
1689	                    => self.uniforms.bg_color[3] = 0,
1690	
1691	                    else => {},
1692	                };
1693	
1694	                // Prepare our overlay image for upload (or unload). This
1695	                // has to use our general allocator since it modifies
1696	                // state that survives frames.
1697	                self.images.overlayUpdate(
1698	                    self.alloc,
1699	                    self.overlay,
1700	                ) catch |err| {
1701	                    log.warn("error updating overlay images err={}", .{err});
1702	                };
1703	
1704	                // Update custom shader uniforms that depend on terminal state.
1705	                self.updateCustomShaderUniformsFromState();
1706	            }
1707	
1708	            // Start the display link now that the rebuilt frame is ready.
1709	            self.syncDisplayLink(null, null);
1710	        }

     1	//! Represents the renderer thread logic. The renderer thread is able to
     2	//! be woken up to render.
     3	pub const Thread = @This();
     4	
     5	const std = @import("std");
     6	const builtin = @import("builtin");
     7	const global = @import("../global.zig");
     8	const xev = global.xev;
     9	const crash = @import("../crash/main.zig");
    10	const internal_os = @import("../os/main.zig");
    11	const rendererpkg = @import("../renderer.zig");
    12	const apprt = @import("../apprt.zig");
    13	const configpkg = @import("../config.zig");
    14	const terminalpkg = @import("../terminal/main.zig");
    15	const BlockingQueue = @import("../datastruct/main.zig").BlockingQueue;
    16	
    17	const Allocator = std.mem.Allocator;
    18	const log = std.log.scoped(.renderer_thread);
    19	
    20	const CURSOR_BLINK_INTERVAL = 600;
    21	
    22	/// Whether calls to `drawFrame` must be done from the app thread.
    23	///
    24	/// The type used for sending messages to the IO thread. For now this is
    25	/// hardcoded with a capacity. We can make this a comptime parameter in
    26	/// the future if we want it configurable.
    27	pub const Mailbox = BlockingQueue(rendererpkg.Message, 64);
    28	
    29	/// Allocator used for some state
    30	alloc: std.mem.Allocator,
    31	
    32	/// The main event loop for the application. The user data of this loop
    33	/// is always the allocator used to create the loop. This is a convenience
    34	/// so that users of the loop always have an allocator.
    35	loop: xev.Loop,
    36	
    37	/// This can be used to wake up the renderer and force a render safely from
    38	/// any thread.
    39	wakeup: xev.Async,
    40	wakeup_c: xev.Completion = .{},
    41	
    42	/// This can be used to stop the renderer on the next loop iteration.
    43	stop: xev.Async,
    44	stop_c: xev.Completion = .{},
    45	
    46	/// The timer used for animations (custom shaders, Kitty graphics).
    47	/// Normal rendering is driven by wakeup messages instead.
    48	render_h: xev.Timer,
    49	render_c: xev.Completion = .{},
    50	render_c_cancel: xev.Completion = .{},
    51	
    52	/// The kind of work the currently scheduled animation wake needs,
    53	/// stored when the timer is armed.
    54	animation_wake: rendererpkg.Renderer.AnimationWake.Kind = .draw,
    55	
    56	/// This async is used to force a draw immediately. This does not
    57	/// coalesce like the wakeup does.
    58	draw_now: xev.Async,
    59	draw_now_c: xev.Completion = .{},
    60	
    61	/// The timer used for cursor blinking
    62	cursor_h: xev.Timer,
    63	cursor_c: xev.Completion = .{},
    64	cursor_c_cancel: xev.Completion = .{},
    65	
    66	/// Incremental scrollback compression scheduling.
    67	compression: Compression = undefined,
    68	
    69	/// The surface we're rendering to.
    70	surface: *apprt.Surface,
    71	
    72	/// The underlying renderer implementation.
    73	renderer: *rendererpkg.Renderer,
    74	
    75	/// Pointer to the shared state that is used to generate the final render.
    76	state: *rendererpkg.State,
    77	
    78	/// The mailbox that can be used to send this thread messages. Note
    79	/// this is a blocking queue so if it is full you will get errors (or block).
    80	mailbox: *Mailbox,
    81	
    82	/// Configuration we need derived from the main config.
    83	config: DerivedConfig,
    84	
    85	flags: packed struct {
    86	    /// This is true when a blinking cursor should be visible and false
    87	    /// when it should not be visible. This is toggled on a timer by the
    88	    /// thread automatically.
    89	    cursor_blink_visible: bool = false,
    90	
    91	    /// This is true when the inspector is active.
    92	    has_inspector: bool = false,
    93	
    94	    /// This is true when the view is visible. This is used to determine
    95	    /// if we should be rendering or not.
    96	    visible: bool = true,
    97	
    98	    /// This is true when the view is focused. This defaults to true
    99	    /// and it is up to the apprt to set the correct value.
   100	    focused: bool = true,
   101	} = .{},
   102	
   103	pub const DerivedConfig = struct {
   104	    scrollback_compression: bool,
   105	
   106	    pub fn init(config: *const configpkg.Config) DerivedConfig {
   107	        return .{
   108	            .scrollback_compression = config.@"scrollback-compression",
   109	        };
   110	    }
   111	};
   112	
   113	/// Initialize the thread. This does not START the thread. This only sets
   114	/// up all the internal state necessary prior to starting the thread. It
   115	/// is up to the caller to start the thread with the threadMain entrypoint.
   116	pub fn init(
   117	    alloc: Allocator,
   118	    config: *const configpkg.Config,
   119	    surface: *apprt.Surface,
   120	    renderer_impl: *rendererpkg.Renderer,
   121	    state: *rendererpkg.State,
   122	) !Thread {
   123	    // Create our event loop.
   124	    var loop = try xev.Loop.init(.{});
   125	    errdefer loop.deinit();
   126	
   127	    // This async handle is used to "wake up" the renderer and force a render.
   128	    var wakeup_h = try xev.Async.init();
   129	    errdefer wakeup_h.deinit();
   130	
   131	    // This async handle is used to stop the loop and force the thread to end.
   132	    var stop_h = try xev.Async.init();
   133	    errdefer stop_h.deinit();
   134	
   135	    // The primary timer for rendering.
   136	    var render_h = try xev.Timer.init();
   137	    errdefer render_h.deinit();
   138	
   139	    // Draw now async, see comments.
   140	    var draw_now = try xev.Async.init();
   141	    errdefer draw_now.deinit();
   142	
   143	    // Setup a timer for blinking the cursor
   144	    var cursor_timer = try xev.Timer.init();
   145	    errdefer cursor_timer.deinit();
   146	
   147	    // The mailbox for messaging this thread
   148	    var mailbox = try Mailbox.create(alloc);
   149	    errdefer mailbox.destroy(alloc);
   150	
   151	    var result: Thread = .{
   152	        .alloc = alloc,
   153	        .config = .init(config),
   154	        .loop = loop,
   155	        .wakeup = wakeup_h,
   156	        .stop = stop_h,
   157	        .render_h = render_h,
   158	        .draw_now = draw_now,
   159	        .cursor_h = cursor_timer,
   160	        .surface = surface,
   161	        .renderer = renderer_impl,
   162	        .state = state,
   163	        .mailbox = mailbox,
   164	    };
   165	
   166	    // Only enable compression if we have it enabled... save some
   167	    // minor resources.
   168	    if (comptime terminalpkg.compression_enabled) {
   169	        result.compression = try .init();
   170	    }
   171	
   172	    return result;
   173	}
   174	
   175	/// Clean up the thread. This is only safe to call once the thread
   176	/// completes executing; the caller must join prior to this.
   177	pub fn deinit(self: *Thread) void {
   178	    self.stop.deinit();
   179	    self.wakeup.deinit();
   180	    self.render_h.deinit();
   181	    self.draw_now.deinit();
   182	    self.cursor_h.deinit();
   183	    if (comptime terminalpkg.compression_enabled)
   184	        self.compression.deinit();
   185	    self.loop.deinit();
   186	
   187	    // Nothing can possibly access the mailbox anymore, destroy it.
   188	    self.mailbox.destroy(self.alloc);
   189	}
   190	
   191	/// The main entrypoint for the thread.
   192	pub fn threadMain(self: *Thread) void {
   193	    // Call child function so we can use errors...
   194	    self.threadMain_() catch |err| {
   195	        // In the future, we should expose this on the thread struct.
   196	        log.warn("error in renderer err={}", .{err});
   197	    };
   198	}
   199	
   200	fn threadMain_(self: *Thread) !void {
   201	    defer log.debug("renderer thread exited", .{});
   202	
   203	    // Right now, on Darwin, `std.Thread.setName` can only name the current
   204	    // thread, and we have no way to get the current thread from within it,
   205	    // so instead we use this code to name the thread instead.
   206	    if (builtin.target.os.tag.isDarwin()) {
   207	        internal_os.macos.pthread_setname_np(&"renderer".*);
   208	    }
   209	
   210	    // Setup our crash metadata
   211	    crash.sentry.thread_state = .{
   212	        .type = .renderer,
   213	        .surface = self.renderer.surface_mailbox.surface,
   214	    };
   215	    defer crash.sentry.thread_state = null;
   216	
   217	    // Setup our thread QoS
   218	    self.setQosClass();
   219	
   220	    // Run our loop start/end callbacks if the renderer cares.
   221	    const has_loop = @hasDecl(rendererpkg.Renderer, "loopEnter");
   222	    if (has_loop) try self.renderer.loopEnter(self);
   223	    defer if (has_loop) self.renderer.loopExit();
   224	
   225	    // Run our thread start/end callbacks. This is important because some
   226	    // renderers have to do per-thread setup. For example, OpenGL has to set
   227	    // some thread-local state since that is how it works.
   228	    try self.renderer.threadEnter(self.surface);
   229	    defer self.renderer.threadExit();
   230	
   231	    // Start the async handlers
   232	    self.wakeup.wait(&self.loop, &self.wakeup_c, Thread, self, wakeupCallback);
   233	    self.stop.wait(&self.loop, &self.stop_c, Thread, self, stopCallback);
   234	    self.draw_now.wait(&self.loop, &self.draw_now_c, Thread, self, drawNowCallback);
   235	
   236	    // Send an initial wakeup message so that we render right away.
   237	    try self.wakeup.notify();
   238	
   239	    // Start blinking the cursor.
   240	    self.cursor_h.run(
   241	        &self.loop,
   242	        &self.cursor_c,
   243	        cursorBlinkInterval(),
   244	        Thread,
   245	        self,
   246	        cursorTimerCallback,
   247	    );
   248	
   249	    // Arm the animation timer in case the renderer already needs
   250	    // animation wakes (e.g. custom shaders loaded at startup).
   251	    self.armAnimationTimer();
   252	
   253	    // Run
   254	    log.debug("starting renderer thread", .{});
   255	    defer log.debug("starting renderer thread shutdown", .{});
   256	    _ = try self.loop.run(.until_done);
   257	}
   258	
   285	        log.warn("error setting QoS class err={}", .{err});
   286	    }
   287	}
   288	
   289	/// Drain the mailbox.
   290	fn drainMailbox(self: *Thread) !void {
   291	    // There's probably a more elegant way to do this...
   292	    //
   293	    // This is effectively an @autoreleasepool{} block, which we need in
   294	    // order to ensure that autoreleased objects are properly released.
   295	    const pool = if (builtin.target.os.tag.isDarwin())
   296	        @import("objc").AutoreleasePool.init()
   297	    else
   298	        void;
   299	    defer if (builtin.target.os.tag.isDarwin()) pool.deinit();
   300	
   301	    while (self.mailbox.pop(global.io())) |message| {
   302	        log.debug("mailbox message={}", .{message});
   303	        switch (message) {
   304	            .crash => @panic("crash request, crashing intentionally"),
   305	
   306	            .visible => |v| visible: {
   307	                // If our state didn't change we do nothing.
   308	                if (self.flags.visible == v) break :visible;
   309	
   310	                // Set our visible state
   311	                self.flags.visible = v;
   312	
   313	                // Visibility affects our QoS class
   314	                self.setQosClass();
   315	
   316	                // If we became visible then we immediately rebuild cells
   317	                // (renderCallback skips updateFrame while invisible) and
   318	                // draw. Going through renderCallback also reschedules
   319	                // any Kitty graphics animation wakeup that lapsed
   320	                // while we were invisible.
   321	                if (v) _ = renderCallback(self, undefined, undefined, {});
   322	
   323	                // Notify the renderer so it can update any state.
   324	                self.renderer.setVisible(v);
   325	
   326	                // Note that we're explicitly today not stopping any
   327	                // cursor timers, draw timers, etc. These things have very
   328	                // little resource cost and properly maintaining their active
   329	                // state across different transitions is going to be bug-prone,
   330	                // so its easier to just let them keep firing and have them
   331	                // check the visible state themselves to control their behavior.
   332	            },
   333	
   334	            .focus => |v| focus: {
   335	                // If our state didn't change we do nothing.
   336	                if (self.flags.focused == v) break :focus;
   337	
   338	                // Set our state
   339	                self.flags.focused = v;
   340	
   341	                // Focus affects our QoS class
   342	                self.setQosClass();
   343	
   344	                // Set it on the renderer
   345	                try self.renderer.setFocus(v);
   346	
   347	                // Focus gates custom shader animation, so re-arm
   348	                // the animation timer for the new state.
   349	                self.armAnimationTimer();
   350	
   351	                if (!v) {
   352	                    // If we're not focused, then we stop the cursor blink
   353	                    if (self.cursor_c.state() == .active and
   354	                        self.cursor_c_cancel.state() == .dead)
   355	                    {
   356	                        self.cursor_h.cancel(
   357	                            &self.loop,
   358	                            &self.cursor_c,
   359	                            &self.cursor_c_cancel,
   360	                            void,
   361	                            null,
   362	                            cursorCancelCallback,
   363	                        );
   364	                    }
   365	                } else {
   366	                    // If we're focused, we immediately show the cursor again
   367	                    // and then restart the timer.
   368	                    if (self.cursor_c.state() != .active) {
   369	                        self.flags.cursor_blink_visible = true;
   370	                        self.cursor_h.run(
   371	                            &self.loop,
   372	                            &self.cursor_c,
   373	                            cursorBlinkInterval(),
   374	                            Thread,
   375	                            self,
   376	                            cursorTimerCallback,
   377	                        );
   378	                    }
   379	                }
   380	            },
   381	
   382	            .reset_cursor_blink => {
   383	                self.flags.cursor_blink_visible = true;
   384	                if (self.cursor_c.state() == .active) {
   385	                    self.cursor_h.reset(
   386	                        &self.loop,
   387	                        &self.cursor_c,
   388	                        &self.cursor_c_cancel,
   389	                        cursorBlinkInterval(),
   390	                        Thread,
   391	                        self,
   392	                        cursorTimerCallback,
   393	                    );
   394	                }
   395	            },
   396	
   397	            .font_grid => |grid| {
   398	                self.renderer.setFontGrid(grid.grid);
   399	                grid.set.deref(grid.old_key);
   400	            },
   401	
   402	            .presentation_health => |v| self.renderer.setPresentationHealth(v),
   403	
   404	            .resize => |v| self.renderer.setScreenSize(v),
   405	
   406	            .change_config => |config| {
   407	                defer config.alloc.destroy(config.thread);
   408	                defer config.alloc.destroy(config.impl);
   409	                try self.changeConfig(config.thread);
   410	                try self.renderer.changeConfig(config.impl);
   411	
   412	                // The config affects what animation wakes the
   413	                // renderer needs (custom shaders, animation mode).
   414	                self.armAnimationTimer();
   415	            },
