125	pub const DisplayCallback = ?*align(8) const fn (?*anyopaque) void;
126	
127	pub fn setDisplayCallback(
128	    self: *IOSurfaceLayer,
129	    display_cb: DisplayCallback,
130	    display_ctx: ?*anyopaque,
131	) void {
132	    self.layer.setInstanceVariable(
133	        "display_cb",
134	        objc.Object.fromId(@constCast(display_cb)),
135	    );
136	    self.layer.setInstanceVariable(
137	        "display_ctx",
138	        objc.Object.fromId(display_ctx),
139	    );
140	}
