142	fn getSubclass() error{ObjCFailed}!objc.Class {
143	    if (Subclass) |c| return c;
144	
145	    const CALayer =
146	        objc.getClass("CALayer") orelse return error.ObjCFailed;
147	
148	    var subclass =
149	        objc.allocateClassPair(CALayer, "IOSurfaceLayer") orelse return error.ObjCFailed;
150	    errdefer objc.disposeClassPair(subclass);
151	
152	    if (!subclass.addIvar("display_cb")) return error.ObjCFailed;
153	    if (!subclass.addIvar("display_ctx")) return error.ObjCFailed;
154	
155	    subclass.replaceMethod("display", struct {
156	        fn display(target: objc.c.id, sel: objc.c.SEL) callconv(.c) void {
157	            _ = sel;
158	            const self = objc.Object.fromId(target);
159	            const display_cb: DisplayCallback = @ptrFromInt(@intFromPtr(
160	                self.getInstanceVariable("display_cb").value,
161	            ));
162	            if (display_cb) |cb| cb(
163	                @ptrCast(self.getInstanceVariable("display_ctx").value),
164	            );
165	        }
166	    }.display);
167	
168	    // Disable all animations for this layer by returning null for all actions.
169	    subclass.replaceMethod("actionForKey:", struct {
170	        fn actionForKey(
171	            target: objc.c.id,
172	            sel: objc.c.SEL,
173	            key: objc.c.id,
174	        ) callconv(.c) objc.c.id {
175	            _ = target;
176	            _ = sel;
177	            _ = key;
178	            return objc.getClass("NSNull").?.msgSend(objc.c.id, "null", .{});
179	        }
180	    }.actionForKey);
181	
182	    objc.registerClassPair(subclass);
183	
184	    Subclass = subclass;
185	
186	    return subclass;
187	}
