 18	/// Options for beginning a frame.
 19	pub const Options = struct {
 20	    /// MTLCommandQueue
 21	    queue: objc.Object,
 22	};
 23	
 24	/// MTLCommandBuffer
 25	buffer: objc.Object,
 26	
 27	block: CompletionBlock.Context,
