   313	    /// Note that this will accumulate garbage in the release pool. The
   314	    /// caller must ensure you're properly calling endFrame to release
   315	    /// all the objects.
   316	    pub fn shape(
   317	        self: *Shaper,
   318	        run: font.shape.TextRun,
   319	    ) ![]const font.shape.Cell {
   320	        const state = &self.run_state;
   321	
   322	        // {
   323	        //     log.debug("shape -----------------------------------", .{});
   324	        //     for (state.codepoints.items) |entry| {
   325	        //         log.debug("cp={X} cluster={}", .{ entry.codepoint, entry.cluster });
   326	        //     }
   327	        //     log.debug("shape end -------------------------------", .{});
   328	        // }
   329	
   330	        // Special fonts aren't shaped and their codepoint == glyph so we
   331	        // can just return the codepoints as-is.
   332	        if (run.font_index.special() != null) {
   333	            self.cell_buf.clearRetainingCapacity();
   334	            try self.cell_buf.ensureTotalCapacity(self.alloc, state.codepoints.items.len);
   335	            for (state.codepoints.items) |entry| {
   336	                // We use null codepoints to pad out our list so indices match
   337	                // the UTF-16 string we constructed for CoreText. We don't want
   338	                // to emit these if this is a special font, since they're not
   339	                // part of the original run.
   340	                if (entry.codepoint == 0) continue;
