   386	
   387	        // This keeps track of the current x offset (sum of advance.width) and
   388	        // the furthest cluster we've seen so far (max).
   389	        var run_offset: Offset = .{};
   390	
   391	        // This keeps track of the cell starting x and cluster.
   392	        var cell_offset: Offset = .{};
   393	
   394	        // For debugging positions, turn this on:
   395	        //var run_offset_y: f64 = 0.0;
   396	        //var cell_offset_y: f64 = 0.0;
   397	
   398	        // Clear our cell buf and make sure we have enough room for the whole
   399	        // line of glyphs, so that we can just assume capacity when appending
   400	        // instead of maybe allocating.
   401	        self.cell_buf.clearRetainingCapacity();
