   410	        // CoreText may generate multiple runs even though our input to
   411	        // CoreText is already split into runs by our own run iterator.
   412	        // The runs as far as I can tell are always sequential to each
   413	        // other so we can iterate over them and just append to our
   414	        // cell buffer.
   415	        const runs = line.getGlyphRuns();
   416	        for (0..runs.getCount()) |run_i| {
   417	            const ctrun = runs.getValueAtIndex(macos.text.Run, run_i);
