   422	            // Get our glyphs and positions
   423	            const glyphs = ctrun.getGlyphsPtr() orelse try ctrun.getGlyphs(alloc);
   424	            const advances = ctrun.getAdvancesPtr() orelse try ctrun.getAdvances(alloc);
   425	            const positions = ctrun.getPositionsPtr() orelse try ctrun.getPositions(alloc);
   426	            const indices = ctrun.getStringIndicesPtr() orelse try ctrun.getStringIndices(alloc);
   427	            assert(glyphs.len == advances.len);
   428	            assert(glyphs.len == positions.len);
   429	            assert(glyphs.len == indices.len);
   430	
   431	            for (
   432	                glyphs,
   433	                advances,
   434	                positions,
   435	                indices,
   436	            ) |glyph, advance, position, index| {
   437	                // Our cluster is also our cell X position. If the cluster changes
   438	                // then we need to reset our current cell offsets.
   439	                const cluster = state.codepoints.items[index].cluster;
