   446	                    const is_after_glyph_from_current_or_next_clusters =
   447	                        cluster <= run_offset.cluster;
   448	
   449	                    const is_first_codepoint_in_cluster = blk: {
   450	                        var i = index;
   451	                        while (i > 0) {
   452	                            i -= 1;
   453	                            const codepoint = state.codepoints.items[i];
   454	
   455	                            // Skip surrogate pair padding
   456	                            if (codepoint.codepoint == 0) continue;
