   123	            // case. In the end case, we always assume it is a grapheme
   124	            // break. This isn't strictly true but its how terminals
   125	            // work today.
   126	            const grapheme_break = i == codepoints.len or blk: {
   127	                const cp2: u21 = @intCast(codepoints[i]);
   128	                defer cp1 = cp2;
   129	
   130	                break :blk unicode.graphemeBreak(
   131	                    unicode.table.get(cp1).grapheme_break,
   132	                    unicode.table.get(cp2).grapheme_break,
   133	                    &break_state,
   134	                );
   135	            };
   136	
   137	            // If this is NOT a grapheme break, cp2 is part of a single
   138	            // grapheme cluster and we expect there could be more. We
   139	            // move on to the next codepoint to try again.
   140	            if (!grapheme_break) continue;
   141	
   142	            // This IS a grapheme break, meaning that cp2 is NOT part
   143	            // of cp1. So we need to render the prior grapheme.
   144	            const len = i - start;
   145	            assert(len > 0);
   146	            switch (len) {
   147	                // If we have only a single codepoint then just render it
   148	                // as-is.
   149	                1 => self.cell_buf[cur] = .{
   150	                    .x = @intCast(clusters[start]),
   151	                    .glyph_index = codepoints[start],
   152	                },
   153	
   154	                // We must have multiple codepoints (see assert above). In
   155	                // this case we UTF-8 encode the codepoints and send them
   156	                // to the face to reserve a private glyph index.
   157	                else => {
   158	                    // UTF-8 encode the codepoints in this cluster.
   159	                    const cluster = cluster: {
   160	                        const cluster_points = codepoints[start..i];
   161	                        assert(cluster_points.len == len);
   162	
   163	                        const buf_len = buf_len: {
   164	                            var acc: usize = 0;
   165	                            for (cluster_points) |cp| {
   166	                                acc += try std.unicode.utf8CodepointSequenceLength(
   167	                                    @intCast(cp),
   168	                                );
    18	    /// there are hash collisions, it would result in rendering issues but
    19	    /// the core data would be correct.
    20	    ///
    21	    /// The hash is position-independent within the row by using relative
    22	    /// cluster positions. This allows identical runs in different positions
    23	    /// to share the same cache entry, improving cache efficiency.
    24	    hash: u64,
    25	
    26	    /// The offset in the row where this run started. This is added to the
    27	    /// X position of the final shaped cells to get the absolute position
    28	    /// in the row where they belong.
    29	    offset: u16,
    30	
    31	    /// The total number of cells produced by this run.
    32	    cells: u16,
    33	
    34	    /// The font grid that built this run.
    35	    grid: *font.SharedGrid,
    36	
    37	    /// The font index to use for the glyphs of this run.
    38	    font_index: font.Collection.Index,
    39	};
