    41	/// RunIterator is an iterator that yields text runs.
    42	pub const RunIterator = struct {
    43	    hooks: font.Shaper.RunIteratorHook,
    44	    opts: shape.RunOptions,
    45	    i: usize = 0,
    46	
    47	    pub fn next(self: *RunIterator, alloc: Allocator) !?TextRun {
    48	        const slice = &self.opts.cells;
    49	        const cells: []const terminal.page.Cell = slice.items(.raw);
    50	        const graphemes: []const []const u21 = slice.items(.grapheme);
    51	        const styles: []const terminal.Style = slice.items(.style);
    52	
    53	        // Trim the right side of a row that might be empty
    54	        const max: usize = max: {
    55	            for (0..cells.len) |i| {
    56	                const rev_i = cells.len - i - 1;
    57	                if (!cells[rev_i].isEmpty()) break :max rev_i + 1;
    58	            }
    59	
    60	            break :max 0;
    61	        };
    62	
    63	        // Invisible cells don't have any glyphs rendered,
    64	        // so we explicitly skip them in the shaping process.
    65	        while (self.i < max and
    66	            (cells[self.i].hasStyling() and
    67	                styles[self.i].flags.invisible)) self.i += 1;
    68	
    69	        // We're over at the max
    70	        if (self.i >= max) return null;
    71	
    72	        // Track the font for our current run
    73	        var current_font: font.Collection.Index = .{};
    74	
    75	        // Allow the hook to prepare
    76	        self.hooks.prepare();
    77	
    78	        // Initialize our hash for this run.
    79	        var hasher = Hasher.init(0);
    80	
    81	        // Let's get our style that we'll expect for the run.
    82	        const style: terminal.Style = if (cells[self.i].hasStyling()) styles[self.i] else .{};
    83	
    84	        // Go through cell by cell and accumulate while we build our run.
    85	        var j: usize = self.i;
    86	        while (j < max) : (j += 1) {
    87	            // Use relative cluster positions (offset from run start) to make
    88	            // the shaping cache position-independent. This ensures that runs
    89	            // with identical content but different starting positions in the
    90	            // row produce the same hash, enabling cache reuse.
    91	            const cluster = j - self.i;
    92	            const cell: *const terminal.page.Cell = &cells[j];
