    94	            // If we have a selection and we're at a boundary point, then
    95	            // we break the run here.
    96	            if (self.opts.selection) |bounds| {
    97	                if (j > self.i) {
    98	                    if (bounds[0] > 0 and j == bounds[0]) break;
    99	                    if (bounds[1] > 0 and j == bounds[1] + 1) break;
