   109	            // If our cell attributes are changing, then we split the run.
   110	            // This prevents a single glyph for ">=" to be rendered with
   111	            // one color when the two components have different styling.
   112	            if (j > self.i) style: {
   113	                const prev_cell = cells[j - 1];
   114	
   115	                // If the prev cell and this cell are both plain
   116	                // codepoints then we check if they are commonly "bad"
   117	                // ligatures and spit the run if they are.
   118	                if (prev_cell.content_tag == .codepoint and
   119	                    cell.content_tag == .codepoint)
