   121	                    const prev_cp = prev_cell.codepoint();
   122	                    switch (prev_cp) {
   123	                        // fl, fi
   124	                        'f' => {
   125	                            const cp = cell.codepoint();
   126	                            if (cp == 'l' or cp == 'i') break;
   127	                        },
   128	
   129	                        // st
   130	                        's' => {
   131	                            const cp = cell.codepoint();
   132	                            if (cp == 't') break;
   133	                        },
   134	
   135	                        else => {},
   136	                    }
   137	                }
   138	
   139	                // If the style is exactly the change then fast path out.
   140	                if (prev_cell.style_id == cell.style_id) break :style;
