216	/// Get the current size of the runtime surface.

   110	    ///
   111	    /// The selection must be a row-only selection (height = 1). See
   112	    /// Selection.containedRow. The run iterator will ONLY look at X values
   113	    /// and assume the y value matches.
   114	    pub fn runIterator(
   115	        self: *Shaper,
   116	        opts: font.shape.RunOptions,
   117	    ) font.shape.RunIterator {
   118	        return .{
   119	            .hooks = .{ .shaper = self },
   120	            .opts = opts,
   121	        };
   122	    }
   123	
   124	    /// Shape the given text run. The text run must be the immediately previous
   125	    /// text run that was iterated since the text run does share state with the
   126	    /// Shaper struct.
   127	    ///
   128	    /// The return value is only valid until the next shape call is called.
   129	    ///
   130	    /// If there is not enough space in the cell buffer, an error is returned.
   131	    pub fn shape(self: *Shaper, run: font.shape.TextRun) ![]const font.shape.Cell {
   132	        // We only do shaping if the font is not a special-case. For special-case
   133	        // fonts, the codepoint == glyph_index so we don't need to run any shaping.
   134	        if (run.font_index.special() == null) {
   135	            // We have to lock the grid to get the face and unfortunately
   136	            // freetype faces (typically used with harfbuzz) are not thread
   137	            // safe so this has to be an exclusive lock.
   138	            run.grid.lock.lockUncancelable(global.io());
   139	            defer run.grid.lock.unlock(global.io());
   140	
   141	            const face = try run.grid.resolver.collection.getFace(run.font_index);
   142	            const i = if (!face.quirks_disable_default_font_features) 0 else i: {
   143	                // If we are disabling default font features we just offset
   144	                // our features by the hardcoded items because always
   145	                // add those at the beginning.
   146	                break :i default_features.len;
   147	            };
   148	
   149	            harfbuzz.shape(face.hb_font, self.hb_buf, self.hb_feats[i..]);
   150	        }
   151	
   152	        // If our buffer is empty, we short-circuit the rest of the work
   153	        // return nothing.
   154	        if (self.hb_buf.getLength() == 0) return self.cell_buf.items[0..0];
   155	        const info = self.hb_buf.getGlyphInfos();
   156	        const pos = self.hb_buf.getGlyphPositions() orelse return error.HarfbuzzFailed;
   157	
   158	        // This is perhaps not true somewhere, but we currently assume it is true.
   159	        // If it isn't true, I'd like to catch it and learn more.
   160	        assert(info.len == pos.len);
   161	
   162	        // This keeps track of the current x and y offsets (sum of advances)
   163	        // and the furthest cluster we've seen so far (max).
   164	        var run_offset: RunOffset = .{};
   165	
   166	        // This keeps track of the cell starting x and cluster.
   167	        var cell_offset: CellOffset = .{};
   168	
   169	        // Convert all our info/pos to cells and set it.
   170	        self.cell_buf.clearRetainingCapacity();
   171	        for (info, pos) |info_v, pos_v| {
   172	            // info_v.cluster is the index into our codepoints array. We use it
   173	            // to get the original cluster.
   174	            const index = info_v.cluster;
   175	            // Our cluster is also our cell X position. If the cluster changes
   176	            // then we need to reset our current cell offsets.
   177	            const cluster = self.codepoints.items[index].cluster;
   178	            if (cell_offset.cluster != cluster) {
   179	                const is_after_glyph_from_current_or_next_clusters =
   180	                    cluster <= run_offset.cluster;
   181	
   182	                const is_first_codepoint_in_cluster = blk: {
   183	                    var i = index;
   184	                    while (i > 0) {
   185	                        i -= 1;
   186	                        const codepoint = self.codepoints.items[i];
   187	                        break :blk codepoint.cluster != cluster;
   188	                    } else break :blk true;
   189	                };
   190	
   191	                // We need to reset the `cell_offset` at the start of a new
   192	                // cluster, but we do that conditionally if the codepoint
   193	                // `is_first_codepoint_in_cluster` and the cluster is not
   194	                // `is_after_glyph_from_current_or_next_clusters`, which is
   195	                // a heuristic to detect ligatures and avoid positioning
   196	                // glyphs that mark ligatures incorrectly. The idea is that
   197	                // if the first codepoint in a cluster doesn't appear in
   198	                // the stream, it's very likely that it combined with
   199	                // codepoints from a previous cluster into a ligature.
   200	                // Then, the subsequent codepoints are very likely marking
   201	                // glyphs that are placed relative to that ligature, so if
   202	                // we were to reset the `cell_offset` to align it with the
   203	                // grid, the positions would be off. The
   204	                // `!is_after_glyph_from_current_or_next_clusters` check is
   205	                // needed in case these marking glyphs come from a later
   206	                // cluster but are rendered first (see the Chakma and
   207	                // Bengali tests). In that case when we get to the
   208	                // codepoint that `is_first_codepoint_in_cluster`, but in a
   209	                // cluster that
   210	                // `is_after_glyph_from_current_or_next_clusters`, we don't
   211	                // want to reset to the grid and cause the positions to be
   212	                // off. (Note that we could go back and align the cells to
   213	                // the grid starting from the one from the cluster that
   214	                // rendered out of order, but that is more complicated so
   215	                // we don't do that for now. Also, it's TBD if there are
   216	                // exceptions to this heuristic for detecting ligatures,
   217	                // but using the logging below seems to show it works
   218	                // well.)
   219	                if (is_first_codepoint_in_cluster and
   220	                    !is_after_glyph_from_current_or_next_clusters)
   221	                {
   222	                    cell_offset = .{
   223	                        .cluster = cluster,
   224	                        .x = run_offset.x,
   225	                    };
   226	                }
   227	            }
   228	
   229	            // Under both FreeType and CoreText the harfbuzz scale is
   230	            // in 26.6 fixed point units, so we round to the nearest
   231	            // whole value here.
