323	        // then it has no outlines or they're too small to render.
324	        //
325	        // In this case we just return 0-sized glyph struct.
326	        if (rect.size.width < 0.25 or rect.size.height < 0.25)
327	            return font.Glyph{
328	                .width = 0,
329	                .height = 0,
330	                .offset_x = 0,
331	                .offset_y = 0,
332	                .atlas_x = 0,
333	                .atlas_y = 0,
334	            };
335	
336	        const metrics = opts.grid_metrics;
364	        // cell width if it's larger than the face width, so that they
365	        // aren't weirdly off to the left.
366	        //
367	        // We don't do this if the glyph has a stretch constraint,
368	        // since in that case the position was already calculated with the
369	        // new cell width in mind.
370	        if (constraint.size != .stretch) {
371	            // We add half the difference to re-center.
372	            const dx = (cell_width - metrics.face_width) / 2;
373	            x += dx;
374	            if (dx < 0) {
375	                // For negative diff (cell narrower than advance), we remove the
376	                // integer part and only keep the fractional adjustment needed
377	                // for consistent subpixel positioning.
378	                x -= @trunc(dx);
379	            }
380	        }
381	
382	        // If this is a bitmap glyph, it will always render as full pixels,
383	        // not fractional pixels, so we need to quantize its position and
384	        // size accordingly to align to full pixels so we get good results.
385	        if (sbix) {
386	            width = cell_width - @round(cell_width - width - x) - @round(x);
387	            height = cell_height - @round(cell_height - height - y) - @round(y);
388	            x = @round(x);
389	            y = @round(y);
390	        }
391	
392	        // We make an assumption that font smoothing ("thicken")
393	        // adds no more than 1 extra pixel to any edge. We don't
394	        // add extra size if it's a sbix color font though, since
395	        // bitmaps aren't affected by smoothing.
396	        const canvas_padding: u32 = if (opts.thicken and !sbix) 1 else 0;
