398	        // Our whole-pixel bearings for the final glyph.
399	        // The fractional portion will be included in the rasterized position.
400	        const px_x = @as(i32, @intFromFloat(@floor(x))) - @as(i32, @intCast(canvas_padding));
401	        const px_y = @as(i32, @intFromFloat(@floor(y))) - @as(i32, @intCast(canvas_padding));
