447	        // caching it forever or having to deal with a cache lifetime.
448	        const buf = try alloc.alloc(u8, px_width * px_height * color.depth);
449	        defer alloc.free(buf);
450	        @memset(buf, 0);
451	
452	        const context = macos.graphics.BitmapContext.context;
453	        const ctx = try macos.graphics.BitmapContext.create(
454	            buf,
455	            px_width,
456	            px_height,
457	            8,
458	            px_width * color.depth,
459	            color.space,
460	            color.context_opts,
