462	        defer context.release(ctx);
463	
464	        // Perform an initial fill. This ensures that we don't have any
465	        // uninitialized pixels in the bitmap.
466	        if (color.color)
467	            context.setRGBFillColor(ctx, 0, 0, 0, 0)
