469	            context.setGrayFillColor(ctx, 0, 0);
470	        context.fillRect(ctx, .{
471	            .origin = .{ .x = 0, .y = 0 },
472	            .size = .{
473	                .width = @floatFromInt(px_width),
474	                .height = @floatFromInt(px_height),
475	            },
476	        });
477	
478	        // "Font smoothing" is what we call "thickening", it's an attempt
479	        // to compensate for optical thinning of fonts, but at this point
480	        // it's just something that makes the text look closer to system
481	        // applications if users want that.
482	        context.setAllowsFontSmoothing(ctx, true);
483	        context.setShouldSmoothFonts(ctx, opts.thicken);
484	
485	        // Subpixel positioning allows glyphs to be placed at non-integer
486	        // coordinates. We need this for our alignment.
487	        context.setAllowsFontSubpixelPositioning(ctx, true);
488	        context.setShouldSubpixelPositionFonts(ctx, true);
489	
490	        // We don't want subpixel quantization, since we very carefully
491	        // manage the position of our glyphs ourselves, and dont want to
492	        // mess that up.
493	        context.setAllowsFontSubpixelQuantization(ctx, false);
494	        context.setShouldSubpixelQuantizeFonts(ctx, false);
495	
496	        // Anti-aliasing is self explanatory.
497	        context.setAllowsAntialiasing(ctx, true);
498	        context.setShouldAntialias(ctx, true);
499	
500	        // Set our color for drawing
501	        if (color.color) {
502	            context.setRGBFillColor(ctx, 1, 1, 1, 1);
503	            context.setRGBStrokeColor(ctx, 1, 1, 1, 1);
504	        } else {
505	            const strength: f64 = @floatFromInt(opts.thicken_strength);
506	            context.setGrayFillColor(ctx, strength / 255.0, 1);
507	            context.setGrayStrokeColor(ctx, strength / 255.0, 1);
508	        }
509	
510	        // If we are drawing with synthetic bold then use a fill stroke
511	        // which strokes the outlines of the glyph making a more bold look.
512	        if (self.synthetic_bold) |line_width| {
513	            context.setTextDrawingMode(ctx, .fill_stroke);
514	            context.setLineWidth(ctx, line_width);
515	        }
516	
517	        // Translate our drawing context so that when we draw our
518	        // glyph the bottom/left edge is at the correct sub-pixel
519	        // position. The bottom/left edges are guaranteed to be at
520	        // exactly [0, 0] relative to this because when we call to
521	        // `drawGlyphs`, we pass the negated bearings.
522	        context.translateCTM(
523	            ctx,
524	            frac_x + @as(f64, @floatFromInt(canvas_padding)),
525	            frac_y + @as(f64, @floatFromInt(canvas_padding)),
526	        );
527	
528	        // Scale the drawing context so that when we draw
529	        // our glyph it's stretched to the constrained size.
530	        context.scaleCTM(
531	            ctx,
532	            width / rect.size.width,
533	            height / rect.size.height,
534	        );
535	
536	        // Draw our glyph.
537	        //
538	        // We offset the position by the negated bearings so that the
539	        // glyph is drawn at exactly [0, 0], which is then offset to
540	        // the appropriate fractional position by the translation we
541	        // did before scaling.
542	        self.font.drawGlyphs(&glyphs, &.{.{
543	            .x = -rect.origin.x,
544	            .y = -rect.origin.y,
545	        }}, ctx);
546	
547	        // Write our rasterized glyph to the atlas.
548	        const region = try atlas.reserve(alloc, px_width, px_height);
549	        atlas.set(region, buf);
550	
551	        // This should be the distance from the bottom of
552	        // the cell to the top of the glyph's bounding box.
553	        const offset_y: i32 = px_y + @as(i32, @intCast(px_height));
554	
555	        // This should be the distance from the left of
556	        // the cell to the left of the glyph's bounding box.
557	        const offset_x: i32 = px_x;
558	
559	        return .{
560	            .width = px_width,
561	            .height = px_height,
562	            .offset_x = offset_x,
563	            .offset_y = offset_y,
564	            .atlas_x = region.x,
565	            .atlas_y = region.y,
566	        };
567	    }
