148	    // For special sprites (cursors, underlines, etc.) all sprites are drawn
149	    // by functions from `Special` that share the name of the enum field.
150	    if (cp >= Sprite.start) switch (@as(Sprite, @fromBackingInt(cp))) {
151	        inline else => |sprite| {
152	            return @field(special, @tagName(sprite));
153	        },
154	    };
155	
156	    // Pray that the compiler is smart enough to
157	    // turn this in to a jump table or something...
158	    inline for (ranges) |range| {
159	        if (cp >= range.min and cp <= range.max) return range.draw;
160	    }
161	    return null;
162	}
