152	/// This always forces loading any deferred fonts since we assume that if
153	/// you're looking up an index that the caller plans to use the font. By
154	/// loading the font in this function we can ensure thread-safety on the
155	/// load without complicating future calls.
156	pub fn getIndex(
157	    self: *SharedGrid,
158	    alloc: Allocator,
159	    cp: u32,
160	    style: Style,
161	    p: ?Presentation,
162	) !?Collection.Index {
163	    const key = CodepointKey.from(.{ .style = style, .codepoint = cp, .presentation = p });
164	
165	    // Fast path: the cache has the value. This is almost always true and
166	    // only requires a read lock.
167	    {
168	        self.lock.lockSharedUncancelable(global.io());
169	        defer self.lock.unlockShared(global.io());
170	        if (self.codepoints.get(key)) |v| return v;
171	    }
172	
173	    // Slow path: we need to search this codepoint
174	    self.lock.lockUncancelable(global.io());
175	    defer self.lock.unlock(global.io());
176	
177	    // Try to get it, if it is now in the cache another thread beat us to it.
178	    const gop = try self.codepoints.getOrPut(alloc, key);
179	    if (gop.found_existing) return gop.value_ptr.*;
180	    errdefer self.codepoints.removeByPtr(gop.key_ptr);
181	
182	    // Load a value and cache it. This even caches negative matches.
183	    const value = self.resolver.getIndex(alloc, cp, style, p);
184	    gop.value_ptr.* = value;
185	
186	    if (value) |idx| preload: {
187	        // If the font is a sprite font then we don't need to preload
188	        // because getFace doesn't work with special fonts.
189	        if (idx.special() != null) break :preload;
190	
191	        // Load the face in case its deferred. If this fails then we would've
192	        // failed to load it in the future anyways so we want to undo all
193	        // the caching we did.
194	        _ = try self.resolver.collection.getFace(idx);
195	    }
196	
197	    return value;
198	}
