221	/// Render a codepoint. This uses the first font index that has the codepoint
222	/// and matches the presentation requested. If the codepoint cannot be found
223	/// in any font, an null render is returned.
224	pub fn renderCodepoint(
225	    self: *SharedGrid,
226	    alloc: Allocator,
227	    cp: u32,
228	    style: Style,
229	    p: ?Presentation,
230	    opts: RenderOptions,
231	) !?Render {
232	    // Note: we could optimize the below to use way less locking, but
233	    // at the time of writing this codepath is only called for preedit
234	    // text which is relatively rare and almost non-existent in multiple
235	    // surfaces at the same time.
236	
237	    // Get the font that has the codepoint
238	    const index = try self.getIndex(alloc, cp, style, p) orelse return null;
239	
240	    // Get the glyph for the font
241	    const glyph_index = glyph_index: {
242	        self.lock.lockSharedUncancelable(global.io());
243	        defer self.lock.unlockShared(global.io());
