212	/// Attempts to fit a rectangle of width x height into the node at idx.
213	/// The return value is the y within the texture where the rectangle can be
214	/// placed. The x is the same as the node.
215	fn fit(self: Atlas, idx: usize, width: u32, height: u32) ?u32 {
216	    // If the added width exceeds our texture size, it doesn't fit.
217	    const node = self.nodes.items[idx];
218	    if ((node.x + width) > (self.size - 1)) return null;
219	
220	    // Go node by node looking for space that can fit our width.
221	    var y = node.y;
222	    var i = idx;
223	    var width_left = width;
224	    while (width_left > 0) : (i += 1) {
225	        const n = self.nodes.items[i];
226	        if (n.y > y) y = n.y;
227	
228	        // If the added height exceeds our texture size, it doesn't fit.
229	        if ((y + height) > (self.size - 1)) return null;
230	
231	        width_left -|= n.width;
232	    }
233	
234	    return y;
235	}
236	
237	/// Merge adjacent nodes with the same y value.
238	fn merge(self: *Atlas) void {
239	    var i: usize = 0;
240	    while (i < self.nodes.items.len - 1) {
241	        const node = &self.nodes.items[i];
242	        const next = self.nodes.items[i + 1];
243	        if (node.y == next.y) {
244	            node.width += next.width;
245	            _ = self.nodes.orderedRemove(i + 1);
246	            continue;
247	        }
248	
249	        i += 1;
250	    }
251	}
