python3 - <<'PY'
import json,re,subprocess
from pathlib import Path
from collections import defaultdict
p=Path('/tmp/ghostty-render-map.NnUNAXr3/ranges.txt')
S=dict(zip('sebrgu',['structure','entity','behavior','relationship','guarantee','subsystem'])); R=dict(zip('div',['declaration','implementation','use']))
rows={}; lengths={}; nodes=[]
for row in p.read_text().splitlines():
    head,*fields=row.split(' | '); n,s=head.split(); nodes.append(dict(node=n,scope=[S[c] for c in s])); assert n not in rows
    inherit=[]; ranges=[]
    for f in fields:
        if f.startswith('inherit '): inherit=f.split()[1:]; assert all(k in rows for k in inherit); continue
        for part in f.split():
            path,a,b,r=re.fullmatch(r'(.*):(\d+)-(\d+):([div]+)',part).groups(); a,b=map(int,(a,b)); assert len(set(r))==len(r)
            if path not in lengths: lengths[path]=len(Path(path).read_text().splitlines())
            assert 1<=a<=b<=lengths[path],(n,path,a,b)
            assert not any(f==path and not(y<a or b<x) for f,x,y,_ in ranges),(n,path,a,b)
            ranges.append((path,a,b,r))
    matrix=defaultdict(lambda:defaultdict(set))
    for f,a,b,r in ranges+[q for k in inherit for q in rows[k]]:
        for i in range(a,b+1): matrix[f][i].update(r)
    merged=[]
    for f,ls in sorted(matrix.items()):
        for i,rs in sorted(ls.items()):
            r=''.join(c for c in R if c in rs)
            if merged and (f,i-1,r)==(merged[-1][0],merged[-1][2],merged[-1][3]):
                merged[-1]=(f,merged[-1][1],i,r)
            else: merged.append((f,i,i,r))
    rows[n]=merged
assert set(rows)=={f'n{i}' for i in range(66,78)}
subprocess.run(['git','ls-files','--error-unmatch','--',*lengths],stdout=subprocess.DEVNULL,check=True)
assert not any(any(k in f.split('/') for k in ['build','deps','docs','dist','test','tests','vendor','testdata','scripts']) for f in lengths)
notes=('d1 n72: the terminal lock is released before endUpdate and cell rebuilding; renderCellMap still reads state.mouse outside that lock despite the earlier mouse copy. d1 n77: the embedded entry point calls Surface.draw directly; Metal\'s native bounds-change path calls the renderer directly. OpenGL/GTK uses render-thread GL and main-thread frame compositing, not the Metal resize callback.')
candidate={'diagrams':[{'diagramId':'d1','nodes':sorted(nodes,key=lambda n:int(n['node'][1:])), 'mappings':[dict(node=n,path=f,startLine=a,endLine=b,role=[R[c] for c in r]) for n,rr in rows.items() for f,a,b,r in rr]}],'notes':notes}
p.with_name('candidate-rendering.json').write_text(json.dumps(candidate,indent=2)+'\n')
print(f'{len(rows)} nodes / {sum(map(len,rows.values()))} normalized ranges / {len(lengths)} tracked source files; checkout pinned and unchanged:')
